package com.muxigame.city;
import java.util.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.item.*;

/** All reservations and purchases transfer existing balances; no negative balances or hidden grants. */
public final class CityWorksFinance {
 static int wage(MinecraftServer s,CityData.City c,boolean active){return RuralSettlement.active(s,c.id)&&!CityTrade.urban(s,c.id)?(active?3:3):(active?7:7);}
 static String publicPayer(MinecraftServer s,CityData.City c){var rural=RuralSettlement.get(s);if(rural.state.enabled.contains(c.id)){var head=rural.state.people.values().stream().filter(p->!p.dead&&p.role==RuralRules.Role.MERCHANT&&rural.state.families.get(p.family).city.equals(c.id)).findFirst();if(head.isPresent())return CityEconomy.person(head.get().id);}return CityEconomy.treasury(c.id);}
 static long protectedFood(MinecraftServer s,UUID person){var d=RuralSettlement.get(s);var p=d.state.people.get(person);if(p==null)return 0;var f=d.state.families.get(p.family);if(CityTrade.managed(s,f.city))return FamilyBudget.reserve(s,f);var stocks=d.stocks(f.id);int ready=RuralRules.count(stocks,true)+stocks.stream().mapToInt(v->Arrays.stream(v.cooked).sum()).sum();int grain=RuralRules.count(stocks,false);boolean cook=FamilyLivelihood.processor(s,f)||RuralRules.members(f,d.state.people).stream().anyMatch(v->v.role==RuralRules.Role.COOK||v.role==RuralRules.Role.FARMER);int deficit=Math.max(0,2*RuralRules.demand(f,d.state.people)-ready-(cook?grain:0));int price=d.state.people.values().stream().filter(v->!v.dead&&v.role==RuralRules.Role.MERCHANT&&d.state.families.get(v.family).city.equals(f.city)).mapToInt(v->v.breadPrice).min().orElse(5);var city=CityData.get(s).cities.get(f.city);if(city!=null){var quote=city.housing.market.get("minecraft:bread");if(quote!=null&&quote.stock>0)price=Math.max(1,(quote.priceCents+50)/100);}if(CityTrade.managed(s,f.city))price=CityTrade.get(s).quote(s,f.city,1,d.state.simulationTicks);return (long)deficit*price;}
 static long spendable(MinecraftServer s,String account){var e=CityEconomy.get(s);long balance=e.balance(account);if(account.startsWith("person:")){UUID id=UUID.fromString(account.substring(7));var d=RuralSettlement.get(s);var p=d.state.people.get(id);var f=p==null?null:d.state.families.get(p.family);long familyBalance=f==null?balance:f.members.stream().mapToLong(v->e.balance(CityEconomy.person(v))).sum();balance=Math.min(balance,familyBalance-protectedFood(s,id));}return Math.max(0,balance);}
 // Share only the owner's occupied home maintenance, never unrelated assets or public work.
 static RuralRules.Family sharedHome(MinecraftServer s,CityData.City c,CityHousing.House h,boolean emergency){if(emergency||h==null||!h.personal||h.owner==null||!h.stage.equals("BUILT")||h.beds<=0)return null;var d=RuralSettlement.get(s);var owner=d.state.people.get(h.owner);if(owner==null||owner.dead)return null;var f=d.state.families.get(owner.family);return f!=null&&c.id.equals(f.city)&&h.residents.contains(owner.id)&&RuralRules.members(f,d.state.people).stream().anyMatch(p->h.residents.contains(p.id))?f:null;}
 static long materialBudget(MinecraftServer s,CityData.City c,CityHousing.House h,boolean emergency,String payer,String wagePayer){var f=sharedHome(s,c,h,emergency);if(f==null)return Math.max(0,spendable(s,payer)-(payer.equals(wagePayer)?wage(s,c,true):0));var e=CityEconomy.get(s);var people=RuralRules.members(f,RuralSettlement.get(s).state.people);long cash=people.stream().mapToLong(p->e.balance(CityEconomy.person(p.id))).sum();boolean wageFromFamily=people.stream().anyMatch(p->CityEconomy.person(p.id).equals(wagePayer));return Math.max(0,cash-protectedFood(s,h.owner)-(wageFromFamily?wage(s,c,true):0));}
 static boolean payMaterial(MinecraftServer s,CityData.City c,CityHousing.House h,boolean emergency,String payer,String to,long amount,String kind){if(amount<0||materialBudget(s,c,h,emergency,payer,null)<Math.max(1,amount))return false;var e=CityEconomy.get(s);if(e.balance(to)>CityEconomy.LIMIT-amount)return false;var f=sharedHome(s,c,h,emergency);if(f==null)return transfer(e,payer,to,amount,c.works.clock,kind);long left=amount;var donors=new ArrayList<>(RuralRules.members(f,RuralSettlement.get(s).state.people));donors.sort(Comparator.comparingInt(p->p.id.equals(h.owner)?0:1));for(var p:donors){long n=Math.min(left,e.balance(CityEconomy.person(p.id)));if(n>0){CityEconomy.require(transfer(e,CityEconomy.person(p.id),to,n,c.works.clock,kind),"家庭维修预检后付款失败");left-=n;}if(left==0)break;}CityEconomy.require(left==0,"家庭维修余额变化");return true;}
 static int buyMeals(MinecraftServer s,CityData.City c,RuralRules.Family family,int wanted){var market=c.housing.market.get("minecraft:bread");if(market==null||market.stock<=0)return 0;int price=Math.max(1,(market.priceCents+50)/100),got=0;var e=CityEconomy.get(s);for(int i=0;i<wanted&&market.stock>0;i++){UUID buyer=family.members.stream().filter(id->e.balance(CityEconomy.person(id))>=price).findFirst().orElse(null);if(buyer==null)break;if(!transfer(e,CityEconomy.person(buyer),"market:"+c.id,price,c.works.clock,"CITY_MEAL"))break;market.stock--;market.sold++;c.works.materialsConsumed.merge("minecraft:bread",1L,Long::sum);got++;}return got;}
 static boolean transfer(CityEconomy e,String from,String to,long n,long clock,String kind){if(n<0||e.balance(from)<n||e.balance(to)>CityEconomy.LIMIT-n)return false;if(from.equals(to))return true;e.state.accounts.put(from,e.balance(from)-n);e.state.accounts.put(to,e.balance(to)+n);e.log(clock,kind,from,to,n,"城市维护实际转账");return true;}
 static boolean reserve(MinecraftServer s,CityData.City c,UUID worker,String payer,int amount){String hold="works:"+c.id+":"+worker;var e=CityEconomy.get(s);CityEconomy.require(e.balance(hold)==0,"上段工资尚未结清");return spendable(s,payer)>=amount&&transfer(e,payer,hold,amount,c.works.clock,"WORK_RESERVE");}
 static void settle(MinecraftServer s,CityData.City c,UUID worker,String payer,int reserved,int operations){var e=CityEconomy.get(s);String hold="works:"+c.id+":"+worker;int wage=wage(s,c,operations>0);CityEconomy.require(reserved>=wage&&e.balance(hold)>=reserved,"工资预留不足");CityEconomy.require(transfer(e,hold,CityEconomy.person(worker),wage,c.works.clock,"WORK_WAGE"),"工资结算失败");if(reserved>wage)CityEconomy.require(transfer(e,hold,payer,reserved-wage,c.works.clock,"WORK_RELEASE"),"工资释放失败");c.works.wages+=wage;CityTrade.wageTax(s,c.id,worker,wage);FamilyLivelihood.paid(s,worker);}
 static Map<String,Integer> workbenchInputs(CityData.City c,CityHousing.House h,boolean emergency){return emergency||h==null||!h.personal?c.works.resources:h.materials;}
 static boolean canCraftWorkbench(Map<String,Integer> source){int n=0;for(var e:source.entrySet())if(e.getValue()>0&&CityEconomy.item(e.getKey()).builtInRegistryHolder().is(net.minecraft.tags.ItemTags.PLANKS)){n+=e.getValue();if(n>=4)return true;}return false;}
 static boolean craftWorkbench(CityData.City c,Map<String,Integer> source){if(!canCraftWorkbench(source))return false;int left=4;for(var e:source.entrySet())if(e.getValue()>0&&CityEconomy.item(e.getKey()).builtInRegistryHolder().is(net.minecraft.tags.ItemTags.PLANKS)){int n=Math.min(left,e.getValue());e.setValue(e.getValue()-n);c.works.materialsConsumed.merge(e.getKey(),(long)n,Long::sum);left-=n;if(left==0)break;}CityEconomy.require(left==0,"Workstation recipe input changed during settlement");c.works.crafted.merge("minecraft:crafting_table",1L,Long::sum);c.works.materialsConsumed.merge("minecraft:crafting_table",1L,Long::sum);return true;}
 static boolean material(MinecraftServer s,CityData.City c,CityHousing.House h,net.minecraft.world.level.block.state.BlockState target,boolean emergency){if(target.isAir())return true;String item=net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(target.getBlock().asItem()).toString();String payer=emergency?publicPayer(s,c):h!=null&&h.personal?(h.owner==null?"":CityEconomy.person(h.owner)):publicPayer(s,c);if(payer.isEmpty())return false;var e=CityEconomy.get(s);
  if(CityBlockRules.natural(target)){long cents=c.housing.tails.getOrDefault(payer,0)+1,paid=cents/100;if(!payMaterial(s,c,h,emergency,payer,"market:"+c.id,paid,"TERRAIN_FEE"))return false;c.housing.tails.put(payer,(int)(cents%100));c.works.materialCents++;return true;}
  if((emergency||h==null||!h.personal)&&c.works.resources.getOrDefault(item,0)>0){c.works.resources.merge(item,-1,Integer::sum);c.works.materialsConsumed.merge(item,1L,Long::sum);return true;}
  if((emergency||h==null||!h.personal)&&takeWarehouse(s,c,item)){c.works.materialsConsumed.merge(item,1L,Long::sum);return true;}
  if(h!=null&&h.materials.getOrDefault(item,0)>0){h.materials.merge(item,-1,Integer::sum);c.works.materialsConsumed.merge(item,1L,Long::sum);return true;}
  if(item.equals("minecraft:crafting_table")&&craftWorkbench(c,workbenchInputs(c,h,emergency)))return true;
  var market=c.housing.market.get(item);if(item.equals("minecraft:air")||market==null||market.stock<=0)return false;String tailKey=CityHousing.tailKey(s,c,payer,item);long cents=(long)c.housing.tails.getOrDefault(tailKey,0)+market.priceCents,paid=cents/100;if(!payMaterial(s,c,h,emergency,payer,CityModel.materialAccount(s,c,item),paid,"WORK_MATERIAL"))return false;market.stock--;market.sold++;c.housing.tails.put(tailKey,(int)(cents%100));CityModel.materialSold(s,c,item,1,paid);c.works.materialCents+=market.priceCents;c.works.materialsConsumed.merge(item,1L,Long::sum);return true;
 }
 static boolean hasWarehouse(MinecraftServer s,CityData.City c,String item){var e=CityEconomy.get(s);var level=CityEconomy.level(s,c);String payer=publicPayer(s,c);for(var w:c.warehouses.values()){if(c.works.deferredContainers.contains(w.pos().asLong()))continue;String owner=e.state.warehouseOwners.get(w.id());if(!Objects.equals(owner,payer)&&!Objects.equals(owner,CityEconomy.treasury(c.id)))continue;var box=RuralSettlement.get(s).state.boxes.get(RuralSettlement.key(c.id,w.pos().asLong()));if(box!=null){if(NpcStorage.projected(level,box).stream().anyMatch(stack->CityEconomy.plain(stack,CityEconomy.item(item))))return true;continue;}try{var slots=new CityEconomy.Slots(CityEconomy.warehouse(level,c,w.id()));slots.remove(item,1);return true;}catch(IllegalArgumentException ignored){}}return false;}
 static boolean canMaterial(MinecraftServer s,CityData.City c,CityHousing.House h,net.minecraft.world.level.block.state.BlockState target,boolean emergency,String wagePayer){if(target.isAir())return true;String item=net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(target.getBlock().asItem()).toString();String payer=emergency?publicPayer(s,c):h!=null&&h.personal?(h.owner==null?"":CityEconomy.person(h.owner)):publicPayer(s,c);if(payer.isEmpty())return false;if(!CityBlockRules.natural(target)){if(h!=null&&h.materials.getOrDefault(item,0)>0)return true;if((emergency||h==null||!h.personal)&&(c.works.resources.getOrDefault(item,0)>0||hasWarehouse(s,c,item)))return true;if(item.equals("minecraft:crafting_table")&&canCraftWorkbench(workbenchInputs(c,h,emergency)))return true;var quote=c.housing.market.get(item);if(quote==null||quote.stock==0)return false;}long cost=CityBlockRules.natural(target)?1:c.housing.market.get(item).priceCents;long paid=(cost+c.housing.tails.getOrDefault(CityBlockRules.natural(target)?payer:CityHousing.tailKey(s,c,payer,item),0))/100;return materialBudget(s,c,h,emergency,payer,wagePayer)>=Math.max(1,paid);}
 static boolean takeWarehouse(MinecraftServer s,CityData.City c,String item){var e=CityEconomy.get(s);var level=CityEconomy.level(s,c);String payer=publicPayer(s,c);for(var registered:c.warehouses.values()){if(c.works.deferredContainers.contains(registered.pos().asLong()))continue;String owner=e.state.warehouseOwners.get(registered.id());if(!Objects.equals(owner,payer)&&!Objects.equals(owner,CityEconomy.treasury(c.id)))continue;var ruralBox=RuralSettlement.get(s).state.boxes.get(RuralSettlement.key(c.id,registered.pos().asLong()));if(ruralBox!=null){if(NpcStorage.takeData(level,ruralBox,item))return true;continue;}try{var slots=new CityEconomy.Slots(CityEconomy.warehouse(level,c,registered.id()));slots.remove(item,1);slots.commit();return true;}catch(IllegalArgumentException ignored){}}return false;}
 static int publicMeals(MinecraftServer s,CityData.City c,int wanted){int got=0;var types=new ArrayList<String>();types.add("minecraft:bread");for(Item item:RuralMeat.COOKED)types.add(net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(item).toString());for(String id:types){int n=Math.min(wanted-got,c.works.resources.getOrDefault(id,0));if(n>0){c.works.resources.merge(id,-n,Integer::sum);c.works.materialsConsumed.merge(id,(long)n,Long::sum);got+=n;}if(got==wanted)break;}
  if(got<wanted)for(String id:types){while(got<wanted&&takeWarehouse(s,c,id)){got++;c.works.materialsConsumed.merge(id,1L,Long::sum);}}
  if(got<wanted){var d=RuralSettlement.get(s);var head=d.state.people.values().stream().filter(p->!p.dead&&p.role==RuralRules.Role.MERCHANT&&d.state.families.get(p.family).city.equals(c.id)).findFirst();if(head.isPresent()){var stocks=d.stocks(head.get().family);int bread=RuralRules.take(stocks,true,Math.min(wanted-got,RuralCooking.available(d,head.get(),1,stocks)));got+=bread;d.audit(c.id).breadEaten+=bread;d.state.foodEaten+=bread;for(int i=0;i<5&&got<wanted;i++){int n=RuralMeat.take(stocks,true,i,Math.min(wanted-got,RuralCooking.available(d,head.get(),i+7,stocks)));got+=n;d.audit(c.id).meatEaten+=n;}d.setDirty();}}
  c.works.emergencyMeals+=got;return got;
 }
}
